/* Throwaway presentation experiment. All file paths, records, counts and mutations are synthetic. */
const variants = { A: 'Guided task sheet', B: 'Review workbench', C: 'Change ledger' };
let variant = new URLSearchParams(location.search).get('variant')?.toUpperCase() || 'A';
if (!variants[variant]) variant = 'A';
let state, timer;
const app = document.querySelector('#app');
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHtml;
const names = {summary:'Proposal summary',compatible:'Compatible changes',conflicts:'Conflicts',mapping:'Category & tag mapping',choices:'Other explicit choices',blockers:'Safety blockers',checkpoint:'Final check',history:'History & storage',source:'Archive & vault',onboard:'Establish update history',recovery:'Recover interrupted update',complete:'Update completed',undo:'Review Undo',support:'Setup & history guidance'};
const sourceText = '# Decision records\n\nRecord the decision and its alternatives.\nReview records every six months.\n\n## Related\n- [[Architecture]]';
const vaultText = '# Decision records\n\nRecord the decision, context, and owner.\nReview records before each major release.\n\n## Related\n- [[Architecture]]\n- [[Team agreements]]';
const combinedText = '# Decision records\n\nRecord the decision, context, alternatives, and owner.\nReview records before each major release and at least every six months.\n\n## Related\n- [[Architecture]]\n- [[Team agreements]]';
function reset(scenario='review') {
  clearInterval(timer);
  state = { scenario, view:'summary', conflictTab:'text', compatible:false, text:null, binary:null, binaryLinks:null,binarySaved:false,
    editor:combinedText, categories:{Method:null,Person:null,Project:null}, tags:{Reviewed:null,Reference:null}, config:null,
    identity:null, excluded:false, stale:false, refreshed:false, saved:false, pause:false,checkpoint:false,
    progress:0,operation:'idle', recovery:null,recoveryEdit:null,undoDecision:null,undoChoice:null,
    baseline:null,uncertain:false, search:'', ledgerOpen:'summary',
    archive:'Software Engineering · 2026-10-18.brz',vault:'C:\\Knowledge\\Engineering',incoming:'same', notice:'' };
  if (scenario==='select') state.view='source';
  if (scenario==='onboard') {state.view='onboard';state.legacy=true;}
  if (['ready','stale','recovery','complete'].includes(scenario)) resolveAll();
  if (scenario==='ready') state.view='checkpoint';
  if (scenario==='stale') {state.view='summary';state.saved=true;state.stale=true;state.text=null;}
  if (scenario==='recovery') {state.view='recovery';state.operation='interrupted';state.progress=43;state.recoveryEdit=null;}
  if (scenario==='complete') {state.view='complete';state.operation='completed';state.progress=100;}
  if (scenario==='support') state.view='support';
  render();
}
function resolveAll(){state.compatible=true;state.text='edit';state.binary='both';state.binaryLinks='incoming';state.binarySaved=true;state.categories={Method:'reuse',Person:'separate',Project:'reuse'};state.tags={Reviewed:'reuse',Reference:'separate'};state.config='keep';state.identity='confirmed';state.excluded=true;}
function unresolved(){
  const items=[];
  if(state.sourceDirty)items.push("Prepare a new proposal for the changed source/vault");
  if(!state.compatible) items.push('Compatible changes');
  if(!state.text)items.push('Decision records conflict');
  if(!state.binarySaved)items.push('Architecture diagram conflict');
  for(const [k,v]of Object.entries(state.categories))if(!v)items.push(k+' category');
  for(const [k,v]of Object.entries(state.tags))if(!v)items.push(k+' tag');
  if(!state.config)items.push('Vault configuration');
  if(!state.identity)items.push('Duplicate source identity');
  if(!state.excluded)items.push('Excluded attachment');
  if(state.legacy&&!state.baseline)items.push('History baseline');
  if(state.legacy&&!state.uncertain)items.push('Uncertain original comparison');
  return items;
}
const button=(text,action,primary=false,disabled=false)=>`<button data-action="${action}" class="${primary?'primary':''}" ${disabled?'disabled':''}>${text}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${text}</span>`;
function notify(text){document.querySelector('#notice').textContent=text;clearTimeout(state.noticeTimer);state.noticeTimer=setTimeout(()=>document.querySelector('#notice').textContent='',4200);}
function setView(view){state.view=view;state.ledgerOpen=view;render();}
function summaryStrip(){return `<div class="summary-strip"><div><strong>782</strong><small>compatible changes</small></div><div><strong>391</strong><small>local edits preserved</small></div><div><strong>42</strong><small>source absences retained</small></div><div class="attention"><strong>2</strong><small>conflicts to resolve</small></div><div class="attention"><strong>${!state.identity+!state.excluded}</strong><small>safety blockers open</small></div></div>`;}
function header(){return `<header class="app-header"><div><div class="brand">brz2obsidian</div><h1>${['recovery','complete','undo','support','source','onboard'].includes(state.view)?names[state.view]:(state.incoming==='unrelated'?'Review incoming import':'Review incoming update')}</h1><p class="subtitle">${state.operation==='interrupted'?'An earlier update needs recovery before another operation can begin.':'Keep writing in Obsidian during review. Finish every decision before applying this operation.'}</p></div><div class="header-actions"><small>${state.saved?'Review saved · simulated':state.stale?'Review needs refresh':'Draft review'}</small>${button('Save & close review','save')}${button('Help & history','help')}</div></header>`;}
function context(){const first=state.incoming==='unrelated';return `<div><strong>${e(state.archive)}</strong><div class="path">${e(state.vault)} · Brain ID ${first?'RL-42B8':'SE-7A13'} · ${first?'first import; ordinary notes remain distinct':state.legacy?'history baseline not established':'last update 9 Oct 2026'}</div></div>`;}
function footer(){const blocked=unresolved().length||state.stale||state.operation==='interrupted';return `<footer class="footer"><small>${state.operation==='interrupted'?'New imports and updates are paused until recovery is resolved.':state.operation==='completed'?'This synthetic update is complete. Undo is a separately reviewed reversal.':state.stale?'Affected approvals need fresh comparisons. Saved mappings and unaffected decisions are retained.':unresolved().length?`${unresolved().length} decision groups remain. Nothing will be applied until the whole update is resolved.`:'All review decisions resolved. Recheck the affected files, then pause editing briefly while applying.'}</small><div class="actions">${button('Proposal summary','view:summary')}${button('Continue to final check','view:checkpoint',true,!!blocked)}</div></footer>`;}
function summary(){return `<h2>Review the whole update</h2><p>1,741 files inspected: 1,248 notes, 486 attachments and 7 support files. Incoming source is the export you selected; its date does not establish that it is newer or more complete.</p>${state.saved?`<div class="banner">Reopened saved review. Source, settings and affected vault files are rechecked before approval can be used.</div>`:''}${state.stale?`<div class="banner warning"><strong>Decision records.md changed in the vault after this review.</strong><p>Its conflict decision is invalid. Other saved decisions remain available; review the new comparison after refreshing.</p>${button('Refresh affected comparison','refresh',true)}</div>`:''}${summaryStrip()}<div class="banner"><strong>Your edits and current paths are preserved.</strong><p>391 locally edited files stay as they are. 42 notes or attachments absent from this archive are retained and flagged. 524 files are unchanged.</p></div><div class="table-wrap"><table><thead><tr><th>Review group</th><th>What it means</th><th>Action</th></tr></thead><tbody><tr><td>Compatible changes ${badge(state.compatible?'Approved':'Review summary',state.compatible?'good':'')}</td><td>782 changes, including new notes, compatible source edits and 2 support files. Individual comparisons remain available.</td><td>${button('Review','view:compatible')}</td></tr><tr><td>Conflicts ${badge((!!state.text+!!state.binarySaved)+'/2 resolved','warning')}</td><td>One note and one binary attachment changed on both sides.</td><td>${button('Resolve','view:conflicts')}</td></tr><tr><td>Category & tag mappings</td><td>3 categories and 2 source tags need explicit choices. Matching names are suggestions.</td><td>${button('Choose mappings','view:mapping')}</td></tr><tr><td>Explicit choices</td><td>Vault configuration affects the whole vault. Source renames and restoration of locally deleted notes are optional.</td><td>${button('Review choices','view:choices')}</td></tr><tr><td>Safety blockers</td><td>A duplicated source identifier and an excluded attachment require decisions.</td><td>${button('Resolve blockers','view:blockers')}</td></tr></tbody></table></div><details><summary>Retained absences and unrelated findings</summary><p><strong>Absent from source, retained:</strong> Notes/Service boundaries.md; 17 architecture diagrams; 24 other files. Removing retained files requires a separate cleanup action.</p><p><strong>Unrelated vault finding:</strong> 3 existing links in Personal/Reading.md point to intentionally uncreated targets. They do not block this update.</p><p><strong>Support files:</strong> Templates/Method.md and Guides/Imported collection.md have compatible source changes. Categories/Methods.md has a local introduction that stays intact.</p></details>`;}
function compatible(){return `<h2>Approve compatible changes together</h2><p>The proposal establishes these changes as compatible with the reviewed vault state. You can inspect any comparison before approving this group.</p><div class="panel soft"><div class="row between"><strong>782 compatible file changes</strong>${badge(state.compatible?'Approved':'Awaiting approval',state.compatible?'good':'warning')}</div><p>648 source text edits · 122 new notes · 10 attachment changes · 2 support-file updates. Local additions, relationships, categories, tags and attachment links are protected.</p>${button(state.compatible?'Remove bulk approval':'Approve all 782 compatible changes','approve-compatible',true,state.stale)}</div><div class="row between wrap"><h3>Representative individual comparisons</h3><label>Find a change <input id="change-search" placeholder="e.g. review, template" value="${e(state.search)}"></label></div><div class="table-wrap"><table><thead><tr><th>Path</th><th>Proposal</th><th>Compare</th></tr></thead><tbody id="change-rows">${compatibleRows()}</tbody></table></div><details><summary>Preserved local changes</summary><p>Architecture/Service boundaries.md keeps its current folder and filename, handwritten examples and manually added links. A proposed source title change is offered separately. Tags and category memberships you added in Obsidian remain.</p></details>`;}
const changeRows=[['Notes/Code review.md','Source paragraph updated; local checklist kept','Code review'],['Notes/Incident learning.md','New note; distinct name selected to protect an existing uncreated link','Incident learning'],['Templates/Method.md','Generated example updated; your extra fields kept','Method template'],['Guides/Imported collection.md','Source counts updated; local introduction kept','Imported collection guide'],['Attachments/review-cycle.svg','Source-only attachment update','Review cycle']];
function compatibleRows(){const rows=changeRows.filter(r=>r.join(' ').toLowerCase().includes(state.search.toLowerCase()));return rows.length?rows.map((r,i)=>`<tr><td><strong>${r[2]}</strong><div class="path">${r[0]}</div></td><td>${r[1]}</td><td>${button('Open comparison','sample:'+i)}</td></tr>`).join(''):`<tr><td colspan="3">No representative changes match this search. The full 782-file inventory is simulated.</td></tr>`;}
function conflicts(){return `<div class="item-tabs"><button data-action="tab:text" class="${state.conflictTab==='text'?'active':''}">Note conflict ${badge(state.text?'Resolved':'1')}</button><button data-action="tab:binary" class="${state.conflictTab==='binary'?'active':''}">Attachment conflict ${badge(state.binarySaved?'Resolved':'1')}</button></div>${state.conflictTab==='text'?textConflict():binaryConflict()}`;}
function textConflict(){return `<h2>Decision records</h2><div class="row between wrap"><div class="path">Notes/Architecture/Decision records.md</div>${badge(state.text?'Decision: '+state.text:'Decision required',state.text?'good':'warning')}</div><p>Both the incoming source and vault changed the review guidance. Current filename and folder are kept. ${state.refreshed?'The comparison includes your latest vault edit.':''}</p><details><summary>Show the last reviewed source baseline</summary><pre class="mono"># Decision records\n\nRecord the decision and context.\nReview records annually.\n\n## Related\n- [[Architecture]]</pre></details><div class="compare"><div><h4>Current vault · your edits</h4><pre>${e(vaultText+(state.refreshed?'\n\nOwner: Platform team':''))}</pre></div><div><h4>Incoming source · selected archive</h4><pre>${e(sourceText)}</pre></div></div><label class="field"><span>Editable result</span><textarea id="result-editor" spellcheck="false" aria-label="Editable conflict result">${e(state.editor)}</textarea><small>Prepared combination is an illustrative starting point. Review the wording and links yourself.</small></label><div class="actions">${button('Keep vault version','text:vault')}${button('Accept source version','text:source')}${button('Use my edited result','text:edit',true,state.stale)}</div><p><small>Keeping the vault version is remembered for this reviewed source content. A later source change will be offered for review again.</small></p>${state.text?`<div class="banner">Conflict resolved. ${button('Review attachment next','tab:binary')}</div>`:''}`;}
function binaryConflict(){return `<h2>Architecture diagram</h2><div class="path">Attachments/architecture.png</div><p>This binary attachment changed in the source and the vault. Preview cards stand in for real attachment viewers; no binary merge is implied.</p><div class="compare"><div><h4>Current vault</h4><div class="panel soft mono">┌ Gateway ──────┐<br>│ API → Queue │<br>└───────────────┘</div><small>612 KB · vault annotation: queue boundary</small></div><div><h4>Incoming source</h4><div class="panel soft mono">┌ Gateway ──────────┐<br>│ API → Worker → DB │<br>└───────────────────┘</div><small>684 KB · updated source architecture</small></div></div>${['vault','source','both'].map((v,i)=>`<label class="choice"><input type="radio" name="binary" value="${v}" ${state.binary===v?'checked':''}><span>${['Keep vault attachment','Use incoming attachment','Keep both attachments'][i]}<small>${['Current file and its links stay as they are.','Replace the current attachment at its existing path after checkpoint.','Keep the current path; add incoming content at a distinct path and review links.'][i]}</small></span></label>`).join('')}${state.binary==='both'?`<div class="banner warning"><strong>Keeping both changes imported attachment links.</strong><p class="mono">Current stays: Attachments/architecture.png<br>Incoming added: Attachments/architecture — incoming 2026-10-18.png</p><p>3 imported references are affected. Existing vault links to the current attachment keep their meaning.</p><label class="choice"><input type="radio" name="binary-links" value="incoming" ${state.binaryLinks==='incoming'?'checked':''}><span>Point the 3 imported references to the incoming copy<small>Decision records.md · Deployment.md · System overview.md</small></span></label><label class="choice"><input type="radio" name="binary-links" value="vault" ${state.binaryLinks==='vault'?'checked':''}><span>Keep all 3 references pointing to the current vault copy<small>The incoming copy remains available without changing these links.</small></span></label></div>`:''}<div class="actions">${button('Save attachment decision','save-binary',true,!state.binary||(state.binary==='both'&&!state.binaryLinks))}</div><small>Radio selections are staged; save the decision to confirm. Paths and links are synthetic examples.</small>`;}
const categoryData={Method:['Methods/Method.md','31 imported members join 18 existing members.','Methods — source reference.md'],Person:['People/Person.md','7 imported members stay in the import category.','People — source reference.md'],Project:['Projects/Project.md','12 imported members join 9 existing members.','Projects — source reference.md']};
function mapping(){return `<h2>Choose where classifications belong</h2><p>Names suggest matches; each mapping needs an explicit choice. Reusing a category combines membership through the <code>categories</code> property. Source category prose and attachments stay in a separate linked reference note.</p><div class="banner warning"><strong>Existing “Method” dashboard uses tags.</strong><p>It will not automatically show notes assigned through <code>categories</code>. The existing dashboard stays intact. A compatible view is offered as a separate reviewed file; automatic adaptation of custom queries is outside this prototype.</p></div><h3>Categories</h3>${Object.keys(categoryData).map(k=>`<div class="mapping-row"><div><strong>${k}</strong><div class="path">Source type ID ${k==='Method'?'type-17':k==='Person'?'type-23':'type-08'}</div><small>${categoryData[k][1]}</small></div><div><label for="category-${k}">Mapping for ${k}</label><select id="category-${k}" data-category="${k}"><option value="">Choose explicitly…</option><option value="separate" ${state.categories[k]==='separate'?'selected':''}>Create separate · Imports/Engineering/Categories/${k}</option><option value="reuse" ${state.categories[k]==='reuse'?'selected':''}>Reuse existing · ${categoryData[k][0]}</option></select>${state.categories[k]?`<p><small>${state.categories[k]==='reuse'?`Membership uses [[${categoryData[k][0].replace('.md','')}]]. Source content stays at Imports/Engineering/References/${categoryData[k][2]}.`:'A distinct category and source reference stay with this import.'}</small></p>`:''}${k==='Method'&&state.categories[k]==='reuse'?`<label class="checkline"><input type="checkbox" id="compatible-view" ${state.compatibleView?'checked':''}><span>Add separately reviewed view: <span class="mono">Methods/Imported members.base</span><small style="display:block">Includes all 49 category members; existing tag dashboard remains intact.</small></span></label>`:''}</div></div>`).join('')}<h3 style="margin-top:24px">Vault tags</h3><p><small>Incoming tags stay distinct by default, with a readable Brain prefix. Reuse requires confirmation.</small></p>${['Reviewed','Reference'].map(k=>`<div class="mapping-row"><div><strong>${k}</strong><small style="display:block">Source tag ${k==='Reviewed'?'tag-11':'tag-42'}</small></div><div><label for="tag-${k}">Mapping for ${k}</label><select id="tag-${k}" data-tag="${k}"><option value="">Choose explicitly…</option><option value="separate" ${state.tags[k]==='separate'?'selected':''}>Keep distinct · #engineering/${k.toLowerCase()}</option><option value="reuse" ${state.tags[k]==='reuse'?'selected':''}>Reuse vault tag · #${k.toLowerCase()}</option></select></div></div>`).join('')}<div class="banner" style="margin-top:18px">Mappings are remembered by source identity, including later source renames. A future mapping change is reviewed with affected memberships and links; manually edited memberships are protected.</div>`;}
function choices(){return `<h2>Review choices with wider effects</h2><div class="panel"><h3>Vault configuration · separate explicit choice</h3><p>The archive suggests updating <span class="mono">.obsidian/appearance.json</span>. This affects the whole vault, including unrelated notes.</p>${['keep','accept'].map(v=>`<label class="choice"><input type="radio" name="config" value="${v}" ${state.config===v?'checked':''}><span>${v==='keep'?'Keep current vault configuration':'Accept the proposed configuration change'}<small>${v==='keep'?'No configuration replacement in this operation.':'Illustrative change: add the imported dashboard CSS snippet. Existing vault settings need comparison in production.'}</small></span></label>`).join('')}</div><div class="panel"><h3>Optional source-driven rename</h3><p>Source title: <strong>Service boundaries and ownership</strong><br>Current vault path: <span class="mono">Architecture/Service boundaries.md</span></p><label class="checkline"><input type="checkbox" id="rename" ${state.rename?'checked':''}><span>Propose renaming this vault file and review 14 incoming link changes</span></label><small>Current filename and folder are preserved by default. This choice does not move the note into an import folder.</small></div><div class="panel"><h3>Locally deleted note · source changed</h3><p><strong>Release checklist.md</strong> was deleted in the vault. The source content has changed since then, so restoration can be offered again.</p><label class="checkline"><input type="checkbox" id="restore" ${state.restore?'checked':''}><span>Restore the changed source note (6 links would gain a target)</span></label><small>Kept deleted by default. Repeating this unchanged archive will not repeatedly offer restoration.</small></div><div class="banner">Output format v3 matches the reviewed baseline. A later converter format upgrade would be a separate operation, with its own proposal.</div>`;}
function blockers(){return `<h2>Resolve affected safety blockers</h2><p>These problems affect files this update would change. Unrelated existing vault problems are reported separately.</p><div class="panel"><div class="row between"><h3>Duplicated source identifier</h3>${badge(state.identity?'Confirmed':'Blocks application',state.identity?'good':'danger')}</div><p>Two incoming records share ID <span class="mono">thought-00a9</span>. A matching title cannot establish identity.</p><p>Candidate vault association: <span class="mono">Notes/Distributed tracing.md</span><br>Source candidates: “Distributed tracing” and “Tracing workshop”.</p><label class="field"><span>Resolve the association</span><select id="identity"><option value="">Choose a resolution…</option><option value="confirmed" ${state.identity==='confirmed'?'selected':''}>Confirm “Distributed tracing”; exclude ambiguous workshop record from this operation</option><option value="exclude" ${state.identity==='exclude'?'selected':''}>Exclude both ambiguous records from this operation</option></select><small>This is a simulated user resolution, not a claim that title matching is safe. Production must preserve the explicit association and scope choice.</small></label></div><div class="panel"><div class="row between"><h3>Attachment is excluded from recovery history</h3>${badge(state.excluded?'Included by explicit choice':'Blocks modification',state.excluded?'good':'danger')}</div><p class="mono">Attachments/vendor-contract.pdf · matches existing exclusion *.pdf</p><p>The proposal would modify this file. The converter respects exclusions; it cannot promise recovery of excluded authored content.</p><label class="checkline"><input type="checkbox" id="excluded" ${state.excluded?'checked':''}><span>Explicitly include this attachment in tracking for this operation<small style="display:block">Specific inclusion follows accepted #248 C10. Declining blocks this modification. It is separate from built-in exact-byte storage consent and cannot override a refused filter or repository layout.</small></span></label></div><div class="banner warning"><strong>12 other excluded files are outside the modification set.</strong><p>The checkpoint will not recover them. This limit must be disclosed again before application. No exclusion is silently overridden.</p></div>`;}
function source(){return `<h2>Select the incoming archive and existing vault</h2><p>This demo uses synthetic selections. No real archive is opened and no directory picker or vault write occurs.</p><div class="field-row"><label class="field"><span>Incoming BRZ archive</span><select id="archive"><option value="same" ${state.incoming==='same'?'selected':''}>Software Engineering · 2026-10-18.brz</option><option value="older" ${state.incoming==='older'?'selected':''}>Software Engineering · 2026-09-12 · partial scope.brz</option><option value="unrelated" ${state.incoming==='unrelated'?'selected':''}>Research Library · first import.brz</option></select><small>The selected export is the incoming version, including an older or differently scoped export.</small></label><label class="field"><span>Existing Obsidian vault</span><input id="vault" value="${e(state.vault)}"><small>Illustrative path only. Contents and repository states are simulated.</small></label></div>${state.incoming==='unrelated'?`<div class="banner"><strong>First import of Research Library into this vault.</strong><p>Keep ordinary notes distinct; matching titles do not combine note bodies. Choose categories and tags explicitly during review.</p><label class="field"><span>Import folder</span><input id="import-folder" value="${e(state.importFolder||'Imports/Research Library/')}"></label><small>Incoming filenames also need collision checks: folder separation alone cannot preserve existing link meanings.</small></div>`:`<div class="banner"><strong>Prior import recognized · Software Engineering</strong><p>Source identity matches SE-7A13. Last update: 9 Oct 2026. ${state.incoming==='older'?'This export is older and covers fewer items; absent notes and attachments will be retained.':'Existing notes may have moved; source identity preserves their current vault paths.'}</p></div>`}<div class="panel soft"><h3>Before preparing a review</h3><p>Supported Git installation required · source identity and history checked · repository compatibility assessed before applying.</p><small>Accepted #248 policy targets ordinary complete local vault-root repositories, including dirty/staged work. Advanced or custom-storage configurations are refused initially; capability still needs #244 evidence.</small></div><div class="actions">${button('Prepare simulated proposal','prepare',true,state.operation==='interrupted')}${button('Explore missing history','view:onboard')}${button('Inspect support guidance','view:support')}</div>`;}
function onboard(){return `<h2>This vault has no trusted update baseline</h2><div class="banner warning"><strong>Preserve the current vault while establishing update history.</strong><p>A migration record alone cannot reconstruct the original generated output. The current edited vault cannot be assumed to be an unchanged original.</p></div><p>Example: a converter-created vault from 2025, or notes copied here without converter history. No baseline is inferred automatically.</p><div class="banner warning"><strong>Earlier checkpoints and Undo are unavailable without their actual history.</strong><p>First offer verification and restoration of a complete matching history copy. If no trusted baseline can be restored and no interrupted operation remains, this separately reviewed onboarding can establish future history while preserving current content and uncertainty.</p><small>A known or suspected interruption must be resolved before fresh onboarding. Missing indispensable recovery state needs a separate explicit resolution; current files stay intact.</small></div><h3>Choose baseline evidence</h3><label class="choice"><input type="radio" name="baseline" value="original" ${state.baseline==='original'?'checked':''}><span>Use trustworthy original generated output<small>Synthetic example: original vault copy supplied from the earlier migration. Identity and correspondence still need verification.</small></span></label><label class="choice"><input type="radio" name="baseline" value="uncertain" ${state.baseline==='uncertain'?'checked':''}><span>Original output is unavailable; review uncertain differences<small>Keep current vault content. Establish a baseline only after reviewing differences whose origin cannot be determined.</small></span></label>${state.baseline?`<div class="panel"><h3>Representative uncertain difference</h3><div class="compare"><div><h4>Current vault</h4><p>Code review.md includes a team-specific checklist and a local <code>categories</code> membership.</p></div><div><h4>Incoming source</h4><p>The checklist is absent; source has a different review paragraph. There is no trustworthy prior version proving which text is a local addition.</p></div></div><label class="checkline"><input type="checkbox" id="uncertain" ${state.uncertain?'checked':''}><span>Preserve the current vault version for this uncertain difference and record the reviewed source content</span></label><small>One representative item models a larger uncertainty review; production must enumerate and bind all affected decisions.</small></div>`:''}<div class="actions">${button('Continue to proposal with onboarding choices','onboard-continue',true,!state.baseline||!state.uncertain)}</div><p><small>This follows accepted #248 H03–H07. Restoring matching history must preserve newer files, refs and staged work; onboarding does not recover missing historical bytes or replay old approvals. Implementation details and capability remain for #244/#247.</small></p>`;}
function checkpoint(){const left=unresolved();return `<h2>Final check before applying</h2>${left.length||state.stale?`<div class="banner danger"><strong>Whole-update review is incomplete.</strong><p>${state.stale?'Refresh changed files before applying.':e(left.join(' · '))}</p>${button('Return to proposal','view:summary')}</div>`:`<div class="banner"><strong>All review decisions are resolved.</strong><p>Recheck source, settings and affected vault files now. If assumptions changed, invalidate the affected decisions before any application.</p></div>`}<dl class="fact-list"><dt>Incoming source</dt><dd>${e(state.archive)}</dd><dt>Target vault</dt><dd class="mono">${e(state.vault)}</dd><dt>History checkpoint</dt><dd>Authored notes and attachments, user-created content, and relevant configuration at the boundary. Meaningful local changes captured; no empty history entries.</dd><dt>Recovery limit</dt><dd>12 excluded, unmodified files stay outside converter recovery. The selected vendor-contract.pdf requires explicit inclusion.</dd><dt>History cost</dt><dd>Estimated 38 MB this operation · 1.8 GB retained converter history. Illustrative values; actual storage measurement remains unverified.</dd></dl><label class="checkline"><input type="checkbox" id="checkpoint-consent" ${state.checkpoint?'checked':''}><span>I reviewed the checkpoint scope and excluded-file recovery limits</span></label><label class="checkline"><input type="checkbox" id="pause" ${state.pause?'checked':''}><span>I have briefly paused editing and other tools that change these files<small style="display:block">Editing remains available during review. Keep it paused until application completes or recovery tells you what needs attention.</small></span></label><div class="actions">${button('Recheck & apply simulated update','apply',true,!!left.length||state.stale||!state.checkpoint||!state.pause)}${button('Simulate another vault edit','simulate-edit')}</div><p><small>This experiment does not write a checkpoint or any files. Compatibility and interruption guarantees require separate engineering evidence.</small></p>`;}
function applying(){return `<h2>Applying update · simulated</h2><p>Keep editing paused while affected files are being published. Review decisions have passed the simulated pre-apply check.</p><div class="progress-track"><div id="apply-progress" style="width:${state.progress}%"></div></div><div class="row between"><strong id="apply-percent">${state.progress}%</strong><span id="apply-stage">${state.progress<25?'Recording pre-apply checkpoint':state.progress<80?'Publishing reviewed files':'Verifying accepted result and recording history'}</span></div><ul class="history" style="margin-top:28px"><li><strong>Checkpoint</strong><small id="checkpoint-stage">${state.progress<25?'In progress':'Completed in simulation'}</small></li><li><strong>Publish reviewed files</strong><small id="publish-stage">${state.progress<80?'In progress':'Completed in simulation'}</small></li><li><strong>Verify and record accepted result</strong><small id="verify-stage">${state.progress<80?'Waiting':'In progress'}</small></li></ul><div class="banner warning">A progress bar cannot establish atomic writes or durable recovery. This is only a presentation walkthrough.</div>${button('Simulate interruption & restart','interrupt')}`;}
function recovery(){return `<h2>Recover before starting another update</h2><div class="banner danger"><strong>Update interrupted after some files were published.</strong><p>Operation 2026-10-20-01 · 336 of 782 compatible changes published (synthetic). Checkpoint and operation record found. No automatic reset of the whole vault.</p></div><div class="panel"><h3>Later edit needs review</h3><p>You edited <span class="mono">Notes/Architecture/Decision records.md</span> after interruption. Your new “Owner: Platform team” line must survive recovery.</p><div class="compare"><div><h4>File now</h4><pre>Review before each major release.\nOwner: Platform team</pre></div><div><h4>Expected interrupted result</h4><pre>Review at least every six months.</pre></div></div><label class="choice"><input type="radio" name="recovery-edit" value="preserve" ${state.recoveryEdit==='preserve'?'checked':''}><span>Keep the later edit and use the reviewed combined wording<small>Owner: Platform team stays in the recovered note.</small></span></label><label class="choice"><input type="radio" name="recovery-edit" value="manual" ${state.recoveryEdit==='manual'?'checked':''}><span>Review an edited recovery result below</span></label>${state.recoveryEdit==='manual'?`<textarea id="recovery-editor" aria-label="Edited recovery result">${e(state.recoveryEditor||'Review before each major release and at least every six months.\nOwner: Platform team')}</textarea>`:''}</div><div class="actions">${button('Finish applying with this reviewed recovery','recover:finish',true,!state.recoveryEdit)}${button('Restore affected files with later edit protected','recover:restore',false,!state.recoveryEdit)}</div><p><small>Both choices preserve the reviewed later edit; they differ on the remaining interrupted publication. This is simulated capability. Actual filesystem/restart proof belongs to #244, within the #248 support scope.</small></p>`;}
function complete(){return `<h2>${state.recovered==='restore'?'Interrupted update restored':'Update completed'}</h2><div class="banner"><strong>${state.recovered==='restore'?'Affected files restored; later edit preserved.':'Reviewed update applied; local content protected.'}</strong><p>${state.recovered?'Recovery choice: '+e(state.recovered)+'. Decision records.md retains the reviewed post-interruption edit.':'782 compatible changes and all explicit choices applied in simulation. Both diagram versions are available, with imported links as reviewed.'}</p></div><div class="summary-strip"><div><strong>391</strong><small>local edits preserved</small></div><div><strong>42</strong><small>source absences retained</small></div><div><strong>12</strong><small>excluded files outside recovery</small></div><div><strong>0</strong><small>unresolved decisions</small></div><div><strong>38 MB</strong><small>illustrative history growth</small></div></div><p>You can resume editing. Review details include the accepted proposal, source version, preserved absences, choices and checkpoint scope.</p><div class="actions">${button('Review Undo of latest operation','view:undo',true)}${button('View operation history','view:history')}${button('Show reviewed proposal','view:summary')}</div><p><small>No real operation occurred. Counts and completion results are synthetic. Opening the vault is intentionally absent from this demo.</small></p>`;}
function undo(){return `<h2>Review Undo · latest applied operation</h2><p>Undo prepares a reversal of the most recent import or update. Review it before applying; edits made afterwards need protection. Older-operation Undo is outside the first release.</p><div class="banner warning"><strong>1 note changed after this operation.</strong><p>Decision records.md now includes your “Owner: Platform team” line. The reversal cannot overwrite it silently.</p></div><div class="table-wrap"><table><thead><tr><th>Reversal</th><th>Review effect</th></tr></thead><tbody><tr><td>618 unchanged-since-update files</td><td>Restore their pre-update versions.</td></tr><tr><td>122 added notes and 41 other new files</td><td>Remove only files unchanged since this operation. Later edited files require a decision.</td></tr><tr><td>2 attachment versions and reviewed links</td><td>Reverse incoming copy/link changes after checking for later edits and references.</td></tr><tr><td>Unrelated notes, staged work and branches</td><td>Preserve them. The reversal applies to the reviewed operation's affected files.</td></tr></tbody></table></div><div class="panel"><h3>Resolve later edit</h3><label class="choice"><input type="radio" name="undo-choice" value="keep" ${state.undoChoice==='keep'?'checked':''}><span>Keep the current note while reversing the rest<small>Owner: Platform team and current note content are retained; this explicit difference appears in the Undo record.</small></span></label><label class="choice"><input type="radio" name="undo-choice" value="edit" ${state.undoChoice==='edit'?'checked':''}><span>Use an edited reversal that includes the later edit</span></label>${state.undoChoice==='edit'?`<textarea id="undo-editor" aria-label="Edited Undo result">${e(state.undoEditor||'Record the decision, context, and owner.\nReview records before each major release.\nOwner: Platform team')}</textarea>`:''}</div><label class="checkline"><input type="checkbox" id="undo-pause" ${state.undoPause?'checked':''}><span>I reviewed the whole reversal and have paused editing briefly</span></label><div class="actions">${button('Apply reviewed Undo · simulated','undo-apply',true,!state.undoChoice||!state.undoPause||!!state.undoDecision)}${button('Keep the completed update','view:complete')}</div>${state.undoDecision?`<div class="banner" style="margin-top:18px">Reviewed Undo completed in simulation. Later edits were preserved. This is not a production recovery guarantee.</div>`:''}`;}
function historyView(){return `<h2>History and recovery storage</h2><p>The converter manages local Git history. Routine update and recovery actions need no Git commands or GitHub account. There is no second history folder.</p><ul class="history"><li><strong>20 Oct · Incoming update · latest operation</strong><small>Before-apply checkpoint + accepted result · 38 MB illustrative growth · latest-operation Undo available</small></li><li><strong>9 Oct · Previous update</strong><small>Source version and accepted vault result retained · older Undo deferred</small></li><li><strong>1 Oct · First import</strong><small>Baseline required for future reconciliation · retained</small></li></ul><div class="panel soft"><h3>1.8 GB retained converter history · illustrative</h3><p>Authored notes, large attachments and unrelated authored content can increase storage. Checkpoints are retained until you explicitly choose cleanup.</p>${button('Preview history cleanup consequences','cleanup')}<small style="display:block;margin-top:10px">Cleanup must retain the active update baseline and respect independent user Git history. No deletion is offered in this prototype.</small></div><div class="banner warning"><strong>Copying notes does not establish that recovery history travelled.</strong><p>Accepted #248 H02–H08 requires a complete matching history copy and validation at the destination. Notes arriving through Sync or selective copy may lack converter history and old Undo. Offer verified restore or separately reviewed preservation-first onboarding; resolve interruptions first. There is no automatic remote fetch, push or history synchronization.</p></div>${button('Setup and history guidance','view:support')}`;}
function support(){return `<h2>Setup and history guidance</h2><div class="banner"><strong>Accepted initial policy · capability remains conditional</strong><p>The human-approved <a href="https://github.com/FuzzyUn1c0rn/brz2obsidian/issues/248#issuecomment-6298978563" target="_blank" rel="noreferrer">#248 support and history matrix</a> governs these explanatory examples. This UI performs no repository detection, validation or recovery. Actual evidence and exact supported Git capabilities remain for #244/#247.</p></div><div class="panel"><h3>Ordinary local vault-root repositories · conditional target</h3><p>Start local converter-managed history when the vault has no repository and no containing parent repository, or reuse its self-contained non-bare full local repository rooted at the vault. Include staged, unstaged and untracked authored work, even partially staged affected files. New/unborn repositories are included.</p><p>No commit, stash or clean-up demand. Preserve the user's HEAD, branches, staged selection and independent history. Reviewed working-file publication may create new unstaged differences against that preserved index. Existing remotes, ordinary branches and tags alone do not cause refusal; the converter does not contact remotes.</p><small>Conditional target C01–C04. A clean status alone does not prove compatibility.</small></div><div class="panel"><h3>Built-in line-ending or encoding transformations · specific choice</h3><p>Converter snapshots retain the actual bytes on disk, bypassing built-in normalization, encoding and keyword expansion for those snapshots while normal repository settings and staging stay intact. Explain and obtain this scoped storage choice before capturing affected authored content. Declining stops preparation that requires it.</p><small>C05 covers built-in text/eol, autocrlf, working-tree-encoding and ident. It does not permit bypassing custom filters, LFS or refused layouts, and does not promise automatic text merging of every encoding.</small></div><div class="panel"><h3>Custom storage or advanced/shared layouts · refuse initially</h3><p>Applicable clean/smudge/process or encryption filters, unknown storage transforms, LFS-required content, active custom hooks and applicable custom merge/diff/textconv drivers stop preparation before converter history or file changes.</p><p>Also initially refused: linked/shared worktrees or redirected metadata; parent/nested repositories, submodules and bare layouts; sparse/skip-worktree/assume-unchanged states; partial/shallow/alternate object stores and unsupported formats. Missing or damaged required history needs recovery first.</p><p>No “continue anyway”, automatic configuration rewrite, filter/hook bypass, second history store or automatic fetch. Report the detected condition and preserve current content.</p><details><summary>Distinguish active policy from harmless definitions</summary><p>An applicable filter binding matters even if its command is unavailable. Unused driver definitions and inactive sample hook files alone are not active policy. Ordinary ignored caches and remote configuration alone are not refusal reasons.</p><p>Unsafe paths, containment uncertainty, insufficient storage/access and Git ownership refusal also stop preparation. Do not override ownership or repair configuration automatically.</p></details><small>C06–C08, C11–C15. This demo reports policy, not observed detection results.</small></div><div class="panel"><h3>Existing operation or incompatible Git · finish/setup first</h3><p>An existing merge, rebase, sequencer, bisect, unresolved index, competing converter operation or relevant repository lock temporarily stops an ordinary update. Finish the user's operation through their normal workflow; do not abort it, delete foreign locks or alter their index.</p><p>A supported installed Git is required before preparing update history. If missing, unusable or incompatible, provide setup guidance and recheck. Bundling Git is deferred. Exact version/capability range remains an engineering result.</p><small>C09/C17. Read-only policy guidance does not establish that a Git version or state has passed preflight.</small></div><div class="panel"><h3>Notes arrived without history, or the baseline was removed</h3><p>Keep current authored notes intact and explain which older checkpoints and Undo are unavailable. Validate and restore a matching complete history copy when available, preserving newer files, refs and staged work. A path, source ID, migration record or object hash alone cannot reconstruct historical bytes.</p><p>If no trustworthy baseline can be restored and no interrupted operation remains, offer separately reviewed preservation-first onboarding. It preserves present content and uncertain differences and establishes future history; previous approvals are not replayed.</p><p>Resolve any known or suspected interruption before another import/update or fresh onboarding. If required preimages or state are missing, report incomplete recovery and require a separate explicit resolution.</p><div class="actions">${button('Review complete-history copy requirements','restore-preview')}${button('Explore reviewed onboarding','view:onboard')}</div><small>H02–H08. Independent branch history rewrites alone do not imply loss if converter refs, metadata and objects still validate. No automatic remote transport or Sync-based history recovery.</small></div>`;}
function content(view=state.view){if(state.operation==='applying'&&view==='checkpoint')return applying();return ({summary,compatible,conflicts,mapping,choices,blockers,checkpoint,source,onboard,recovery,complete,undo,history:historyView,support}[view]||summary)();}
const reviewViews=['summary','compatible','conflicts','mapping','choices','blockers'];
function activeStep(){return ['source','onboard','support'].includes(state.view)?0:reviewViews.includes(state.view)?1:state.view==='checkpoint'?2:3;}
function VariantA(){return `<div class="shell variant-a">${header()}<nav class="steps" aria-label="Operation steps">${['Choose source','Review proposal','Final check','Result & recovery'].map((s,i)=>`<button data-action="view:${['source','summary','checkpoint',state.operation==='interrupted'?'recovery':'complete'][i]}" class="${activeStep()===i?'active':''}" ${i===3&&!['interrupted','completed'].includes(state.operation)?'disabled':''}><b>${i+1}</b>${s}</button>`).join('')}</nav><div class="a-context">${context()}</div><section class="section task-body">${reviewViews.includes(state.view)?`<nav class="subnav" aria-label="Review groups">${reviewViews.map(v=>`<button data-action="view:${v}" class="${state.view===v?'active':''}">${names[v]}</button>`).join('')}</nav>`:''}${content()}</section>${footer()}</div>`;}
function VariantB(){const queueEntry=(v,label,count)=>`<button data-action="view:${v}" class="${state.view===v?'active':''}"><span>${label}</span>${count!==undefined?badge(count):''}</button>`;return `<div class="shell variant-b">${header()}<div class="workbench-context">${context()}<div class="compact-facts"><span>1,741 files</span><span>782 compatible</span><span>${unresolved().length} decisions open</span></div></div><div class="workbench"><nav class="queue" aria-label="Review queue"><h3>Review queue</h3>${queueEntry('source','Archive & vault')}${queueEntry('summary','Overview')}<div class="queue-group">Review decisions</div>${queueEntry('compatible','Compatible changes',state.compatible?'✓':'782')}${queueEntry('conflicts','Conflicts',!!state.text+!!state.binarySaved+'/2')}${queueEntry('mapping','Categories & tags',Object.values({...state.categories,...state.tags}).filter(Boolean).length+'/5')}${queueEntry('choices','Other choices',state.config?'✓':'1')}${queueEntry('blockers','Safety blockers',!state.identity+!state.excluded)}<div class="queue-group">Apply & recover</div>${queueEntry('checkpoint','Final check')}${state.operation==='interrupted'?queueEntry('recovery','Interrupted update'):''}${state.operation==='completed'?queueEntry('complete','Completed update'):''}${queueEntry('history','History & storage')}${queueEntry('support','Setup & guidance')}<small>Unresolved decisions block the whole operation. Continue editing until you reach the brief application pause.</small></nav><section class="review-pane">${content()}</section></div>${footer()}</div>`;}
function VariantC(){const special=!reviewViews.includes(state.view);const rowMeta={summary:['Overview','1,741','Files, preservation and findings'],compatible:['Compatible changes','782','Approve the group after its summary'],conflicts:['Conflicts','2','Compare both versions and choose a result'],mapping:['Categories & tags','5','Choose a destination for each classification'],choices:['Other explicit choices','1','Configuration, optional rename and restoration'],blockers:['Safety blockers','2','Resolve affected identity and tracking issues']};return `<div class="shell variant-c">${header()}<div class="ledger-context"><div><small>Incoming source</small><h3 style="margin-top:6px">${e(state.archive)}</h3><div class="path">${state.incoming==='unrelated'?'RL-42B8':'SE-7A13'} · selected version, independent of date</div></div><div><small>Vault & operation</small><h3 style="margin-top:6px">Engineering</h3><div class="path">${e(state.vault)} · ${state.incoming==='unrelated'?'first import; distinct ordinary notes':state.legacy?'establish history':'update existing import'}</div></div></div><section class="ledger"><div class="ledger-controls">${button('Archive & vault','view:source')}${button('Change ledger','view:summary')}${button('Final check','view:checkpoint')}${button(state.operation==='interrupted'?'Recovery':'History & storage',state.operation==='interrupted'?'view:recovery':'view:history')}${state.operation==='completed'?button('Result / Undo','view:complete'):''}<span class="muted">${unresolved().length} open decision groups</span></div>${special?content():`<div class="banner ${state.stale?'warning':''}">${state.stale?'Saved review reopened: Decision records.md changed. Refresh its affected comparison before approval. '+button('Refresh comparison','refresh'): 'Work down the ledger, expanding a group to compare and resolve. Compatible changes can be approved together; every conflict and mapping needs an explicit choice.'}</div>${reviewViews.map(v=>`<details class="ledger-row" data-ledger="${v}" ${state.ledgerOpen===v?'open':''}><summary><span class="count">${rowMeta[v][1]}</span><strong>${rowMeta[v][0]}</strong><small>${rowMeta[v][2]}</small>${v==='compatible'?badge(state.compatible?'Approved':'Needs approval',state.compatible?'good':'warning'):v==='conflicts'?badge(state.text&&state.binarySaved?'Resolved':'Needs decisions','warning'):''}</summary><div class="ledger-content">${content(v)}</div></details>`).join('')}`}</section>${footer()}</div>`;}
function captureFocus(){const active=document.activeElement;if(!active||!app.contains(active))return null;return {id:active.id,name:active.name,value:active.value,action:active.dataset.action,start:active.selectionStart,end:active.selectionEnd};}
function restoreFocus(previous){if(!previous)return;let next=previous.id?document.getElementById(previous.id):null;if(!next&&previous.name)next=[...document.getElementsByName(previous.name)].find(el=>el.value===previous.value);if(!next&&previous.action)next=[...app.querySelectorAll('[data-action]')].find(el=>el.dataset.action===previous.action);if(next&&!next.disabled){next.focus({preventScroll:true});if(typeof previous.start==='number'&&next.setSelectionRange)next.setSelectionRange(previous.start,previous.end);}}
function lockDuringOperation(){if(!['applying','interrupted'].includes(state.operation))return;for(const control of app.querySelectorAll('button,input,select,textarea')){const action=control.dataset.action||'';const allowed=state.operation==='applying'?['interrupt','help'].includes(action):action==='help'||['view:recovery','view:history','view:support'].includes(action)||action.startsWith('recover:')||control.name==='recovery-edit'||control.id==='recovery-editor';if(!allowed)control.disabled=true;}}
function render(){const focus=captureFocus();app.innerHTML=({A:VariantA,B:VariantB,C:VariantC}[variant])();document.querySelector('#variant-name').textContent=`${variant} · ${variants[variant]}`;document.querySelector('#state-panel').innerHTML=`<details><summary>Prototype state · ${variant} · ${e(state.view)} · ${unresolved().length} open decision groups · ${state.stale?'stale':state.operation} · expand to inspect</summary><pre>${e(JSON.stringify({scenario:state.scenario,variant,view:state.view,operation:state.operation,compatibleApproved:state.compatible,textDecision:state.text,binaryDecision:state.binary,binaryLinks:state.binaryLinks,binaryConfirmed:state.binarySaved,categories:state.categories,tags:state.tags,configuration:state.config,identity:state.identity,excludedIncluded:state.excluded,baseline:state.baseline,uncertainPreserved:state.uncertain,stale:state.stale,reviewSaved:state.saved,checkpointConsent:state.checkpoint,pauseConfirmed:state.pause,progress:state.progress,recoveryEdit:state.recoveryEdit,undoChoice:state.undoChoice,unresolved:unresolved()},null,2))}</pre></details>`;document.querySelectorAll('details[data-ledger]').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)state.ledgerOpen=el.dataset.ledger;}));lockDuringOperation();restoreFocus(focus);}
function switchVariant(direction){const keys=Object.keys(variants);variant=keys[(keys.indexOf(variant)+direction+keys.length)%keys.length];const url=new URL(location.href);url.searchParams.set('variant',variant);window.history.replaceState({},'',url);render();}
document.querySelector('#previous').onclick=()=>switchVariant(-1);
document.querySelector('#next').onclick=()=>switchVariant(1);
document.addEventListener('keydown',event=>{const target=event.target;if(target.closest('input,textarea,select,[contenteditable=""],[contenteditable="true"],[role="textbox"]')||target.isContentEditable||document.querySelector('dialog[open]')||event.altKey||event.ctrlKey||event.metaKey)return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();switchVariant(event.key==='ArrowRight'?1:-1);}});
document.querySelector('#scenario').onchange=event=>reset(event.target.value);
document.querySelector('#reset').onclick=()=>reset(document.querySelector('#scenario').value);
document.addEventListener('input',event=>{const {id,value}=event.target;if(id==='result-editor')state.editor=value;if(id==='recovery-editor')state.recoveryEditor=value;if(id==='undo-editor')state.undoEditor=value;if(id==='vault'){state.vault=value;state.sourceDirty=true;}if(id==='import-folder'){state.importFolder=value;state.sourceDirty=true;}if(id==='change-search'){state.search=value;document.querySelector('#change-rows').innerHTML=compatibleRows();}});
document.addEventListener('change',event=>{const target=event.target;if(target.dataset.category){state.categories[target.dataset.category]=target.value||null;render();}if(target.dataset.tag){state.tags[target.dataset.tag]=target.value||null;render();}if(target.name==='binary'){state.binary=target.value;state.binaryLinks=null;state.binarySaved=false;render();}if(target.name==='binary-links'){state.binaryLinks=target.value;state.binarySaved=false;render();}if(target.name==='config'){state.config=target.value;render();}if(target.id==='identity'){state.identity=target.value||null;render();}if(target.id==='excluded'){state.excluded=target.checked;render();}if(['pause','checkpoint-consent','uncertain','rename','restore','compatible-view','undo-pause'].includes(target.id)){state[{'checkpoint-consent':'checkpoint','compatible-view':'compatibleView','undo-pause':'undoPause'}[target.id]||target.id]=target.checked;render();}if(target.name==='baseline'){state.baseline=target.value;state.legacy=true;render();}if(target.name==='recovery-edit'){state.recoveryEdit=target.value;render();}if(target.name==='undo-choice'){state.undoChoice=target.value;render();}if(target.id==='archive'){state.sourceDirty=true;state.incoming=target.value;state.archive={same:'Software Engineering · 2026-10-18.brz',older:'Software Engineering · 2026-09-12 · partial scope.brz',unrelated:'Research Library · first import.brz'}[target.value];render();}});
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const [action,arg]=target.dataset.action.split(':');
  if(state.operation==='applying'&&!['interrupt','help','close-help'].includes(action))return;
  if(action==='view'){setView(arg);return;}
  if(action==='tab'){state.conflictTab=arg;state.view='conflicts';state.ledgerOpen='conflicts';render();return;}
  if(action==='text'){if(state.stale){notify('Refresh the affected comparison before saving this decision.');return;}state.text=arg;render();notify('Note decision saved for the reviewed source and vault state.');return;}
  if(action==='approve-compatible'){state.compatible=!state.compatible;render();return;}
  if(action==='save-binary'){state.binarySaved=true;render();notify('Attachment and associated link decisions saved in memory.');return;}
  if(action==='save'){state.saved=true;render();const d=document.querySelector('#support-dialog');d.innerHTML=`<h2>Review saved · simulated close</h2><p>The proposal and decisions would be available after closing the app. This prototype retains them only in the current page memory; reloading resets them.</p><p>Reopening rechecks the source, settings and affected vault state. Unchanged decisions remain; affected decisions become invalid when assumptions change.</p><div class="actions">${button('Resume unchanged saved review','resume:same',true)}${button('Resume after a vault edit','resume:changed')}</div>`;d.showModal();return;}
  if(action==='resume'){document.querySelector('#support-dialog').close();if(arg==='changed'){state.stale=true;state.text=null;state.pause=false;state.checkpoint=false;}setView('summary');return;}
  if(action==='refresh'){state.stale=false;state.refreshed=true;state.text=null;state.pause=false;state.checkpoint=false;state.editor=combinedText+'\n\nOwner: Platform team';setView('conflicts');notify('Affected note comparison refreshed; its previous decision remains invalid. Other decisions retained.');return;}
  if(action==='simulate-edit'){state.stale=true;state.text=null;state.pause=false;state.checkpoint=false;setView('summary');return;}
  if(action==='prepare'){if(state.operation==='interrupted'){notify('Recover the interrupted operation before preparing another update.');return;}if(state.sourceDirty){const selected={vault:state.vault,archive:state.archive,incoming:state.incoming,importFolder:state.importFolder};reset('review');Object.assign(state,selected);}setView('summary');notify('Synthetic proposal prepared. All decisions are illustrative; no archive was read.');return;}
  if(action==='onboard-continue'){setView('summary');return;}
  if(action==='help'){showHelp();return;}
  if(action==='close-help'){document.querySelector('#support-dialog').close();return;}
  if(action==='restore-preview'){const d=document.querySelector('#support-dialog');d.innerHTML=`<h2>Validate a matching complete history copy</h2><p>The copy needs the matching vault association, relevant configuration and actual self-contained converter Git refs, metadata, reachable objects and attachment payloads. A folder-copy label or ordinary clone alone is not proof that converter history travelled.</p><p>Validate completeness and consistency before restore; preserve newer current files, refs and staged work. A copy of an active operation is not a guaranteed consistent backup. Resolve an interruption before ordinary update or fresh onboarding.</p><div class="banner warning">This is read-only guidance. No backup is selected or validated here, no restoration is performed, and no missing historical bytes or previous Undo are declared recovered.</div><div class="actions">${button('Close requirements','close-help',true)}</div>`;d.showModal();return;}
  if(action==='cleanup'){notify('Cleanup preview: removing 2026-10-01 checkpoints would reduce recovery options. Active baseline and independent user history must stay. Nothing deleted.');return;}
  if(action==='sample'){const r=changeRows[Number(arg)]||changeRows[0];const d=document.querySelector('#support-dialog');d.innerHTML=`<h2>${r[2]} · comparison</h2><div class="path">${r[0]}</div><div class="compare"><div><h4>Current vault</h4><pre>Review code with a clear purpose.\n\nTeam checklist:\n- Consider operational risk.</pre></div><div><h4>Proposed result</h4><pre>Review code with a clear purpose.\nUse small, focused review batches.\n\nTeam checklist:\n- Consider operational risk.</pre></div></div><div class="banner">The local checklist is retained. This representative comparison is synthetic, including when selected from another illustrative file row.</div><div class="footer">${button('Close comparison','close-help')}</div>`;d.showModal();return;}
  if(action==='apply'){if(unresolved().length||state.stale||!state.pause||!state.checkpoint)return;state.operation='applying';state.progress=0;render();timer=setInterval(()=>{state.progress=Math.min(100,state.progress+7);if(state.progress===100){clearInterval(timer);state.operation='completed';state.pause=false;state.view='complete';state.ledgerOpen='complete';render();}else{document.querySelector('#apply-progress').style.width=state.progress+'%';document.querySelector('#apply-percent').textContent=state.progress+'%';document.querySelector('#apply-stage').textContent=state.progress<25?'Recording pre-apply checkpoint':state.progress<80?'Publishing reviewed files':'Verifying accepted result and recording history';document.querySelector('#checkpoint-stage').textContent=state.progress<25?'In progress':'Completed in simulation';document.querySelector('#publish-stage').textContent=state.progress<80?'In progress':'Completed in simulation';document.querySelector('#verify-stage').textContent=state.progress<80?'Waiting':'In progress';}},450);return;}
  if(action==='interrupt'){clearInterval(timer);state.operation='interrupted';state.view='recovery';state.recoveryEdit=null;render();return;}
  if(action==='recover'){state.recovered=arg;state.operation='completed';state.progress=100;state.pause=false;setView('complete');return;}
  if(action==='undo-apply'){state.undoDecision='completed';render();notify('Reviewed latest-operation Undo completed in simulation; later edit retained.');return;}
});
function showHelp(){const dialog=document.querySelector('#support-dialog');dialog.innerHTML=`<h2>Review, history and recovery</h2><p>Review decisions are tied to the incoming source, settings and vault state. Saved review can resume after closing the app; changed assumptions invalidate only affected decisions. This demo simulates that persistence without writing a file.</p><p>Converter history is managed locally in Git. Keep vault editing paused only while applying. Existing authored content and relevant configuration are checkpointed, subject to disclosed exclusions.</p><div class="banner warning">Accepted #248 policy targets ordinary complete local vault-root repositories, with specific built-in exact-byte consent and initial advanced/custom-storage refusals. Missing history requires verified restore or reviewed preservation-first onboarding; interruptions come first. Capability remains conditional on #244/#247; this prototype makes no recovery guarantee.</div><div class="actions">${button('Close guidance','close-help',true)}</div>`;dialog.showModal();}
window.addEventListener('popstate',()=>{variant=new URLSearchParams(location.search).get('variant')?.toUpperCase()||'A';if(!variants[variant])variant='A';render();});
reset();
